# Disable 8.3 Short File Name Generation Write-Host "Disabling 8.3 short file name generation on all NTFS volumes..." -ForegroundColor Cyan # Get all NTFS volumes and disable 8.3 naming $volumes = Get-Volume | Where-Object { $_.FileSystem -eq "NTFS" -and $_.DriveLetter } foreach ($vol in $volumes) { $drive = $vol.DriveLetter + ":" fsutil 8dot3name set $drive 1 2>&1 | Out-Null Write-Host "  Disabled 8.3 naming on drive $drive" -ForegroundColor Gray } # Also disable system-wide via registry Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem" -Name "NtfsDisable8dot3NameCreation" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue Write-Host "8.3 short file name generation has been disabled on all NTFS volumes." -ForegroundColor Green